    26→// FileChange represents a markdown file change
    27→type FileChange struct {
    28→	Path     string
    29→	Filename string
    30→	Title    string
    31→	Content  string
    32→}
    33→
    34→// isSupported checks if a file type should be synced
    35→func isSupportedFile(filename string) bool {
    36→	ext := strings.ToLower(filepath.Ext(filename))
    37→
    38→	supportedExts := []string{
    39→		// Markdown
    40→		".md",
    41→		// Images
    42→		".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".svg",
    43→		// PDFs
    44→		".pdf",
    45→		// Videos
    46→		".mp4", ".mov", ".avi", ".mkv", ".webm",
    47→		// Audio
    48→		".mp3", ".wav", ".ogg", ".m4a", ".flac",
    49→	}
    50→
    51→	for _, supported := range supportedExts {
    52→		if ext == supported {
    53→			return true
    54→		}
    55→	}
    56→	return false
    57→}
    58→
    59→// ParseMarkdown extracts title and content from markdown file
    60→func ParseMarkdown(filepath string) (*FileChange, error) {
    61→	content, err := os.ReadFile(filepath)
    62→	if err != nil {
    63→		return nil, err
    64→	}
    65→
    66→	filename := strings.TrimSuffix(filepath[strings.LastIndex(filepath, "/")+1:], ".md")
    67→
    68→	// Extract first heading as title
    69→	title := filename
    70→	lines := strings.Split(string(content), "\n")
    71→	for _, line := range lines {
    72→		if strings.HasPrefix(line, "# ") {
    73→			title = strings.TrimPrefix(line, "# ")
    74→			break
    75→		}
    76→	}
    77→
    78→	return &FileChange{
    79→		Path:     filepath,
    80→		Filename: filename,
    81→		Title:    title,
    82→		Content:  string(content),
    83→	}, nil
    84→}
