    86→// SyncFile processes a file for sync (markdown or binary)
    87→func SyncFile(ctx context.Context, client *AnyTypeClient, filePath string) (string, error) {
    88→	// Check if client is connected
    89→	if client == nil {
    90→		fmt.Printf("[%s] ⚠ File queued (gRPC client not connected)\n", time.Now().Format(time.RFC3339))
    91→		return "", fmt.Errorf("client not connected")
    92→	}
    93→
    94→	// Extract filename without extension for object mapping
    95→	filename := filePath[strings.LastIndex(filePath, "/")+1:]
    96→	ext := filepath.Ext(filename)
    97→	filenameNoExt := strings.TrimSuffix(filename, ext)
    98→
    99→	fmt.Printf("[%s] Syncing %s...\n", time.Now().Format(time.RFC3339), filename)
   100→
   101→	var objectID string
   102→	var err error
   103→
   104→	// Handle different file types
   105→	if strings.HasSuffix(filePath, ".md") {
   106→		// Markdown file - use existing markdown sync
   107→		change, parseErr := ParseMarkdown(filePath)
   108→		if parseErr != nil {
   109→			fmt.Printf("[%s] ✗ Error parsing %s: %v\n", time.Now().Format(time.RFC3339), filePath, parseErr)
   110→			return "", parseErr
   111→		}
   112→
   113→		objectID, err = client.SyncMarkdownWithID(ctx, change, spaceID)
   114→		if err != nil {
   115→			fmt.Printf("[%s] ✗ Sync error for %s: %v\n", time.Now().Format(time.RFC3339), filename, err)
   116→			return "", err
   117→		}
   118→	} else {
   119→		// Binary file (image, PDF, video, audio) - use file upload
   120→		objectID, err = client.uploadFile(ctx, filePath, spaceID)
   121→		if err != nil {
   122→			fmt.Printf("[%s] ✗ Upload error for %s: %v\n", time.Now().Format(time.RFC3339), filename, err)
   123→			return "", err
   124→		}
   125→	}
   126→
   127→	// Store the object ID mapping
   128→	if objectMap != nil {
   129→		if err := objectMap.Set(filenameNoExt, objectID); err != nil {
   130→			fmt.Printf("[%s] ⚠ Failed to save object mapping: %v\n", time.Now().Format(time.RFC3339), err)
   131→		}
   132→	}
   133→
   134→	fmt.Printf("[%s] ✓ %s synced to AnyType (ID: %s)\n", time.Now().Format(time.RFC3339), filename, objectID)
   135→	return objectID, nil
   136→}
