   138→// DeleteFile processes a file deletion
   139→func DeleteFile(ctx context.Context, client *AnyTypeClient, filePath string) {
   140→	// Extract filename and remove extension for object mapping
   141→	filename := filePath[strings.LastIndex(filePath, "/")+1:]
   142→	ext := filepath.Ext(filename)
   143→	filenameNoExt := strings.TrimSuffix(filename, ext)
   144→
   145→	fmt.Printf("[%s] Deleting %s...\n", time.Now().Format(time.RFC3339), filename)
   146→
   147→	// Delete from AnyType via gRPC (if connected)
   148→	if client == nil {
   149→		fmt.Printf("[%s] ⚠ %s delete queued (gRPC client not connected)\n", time.Now().Format(time.RFC3339), filename)
   150→		return
   151→	}
   152→
   153→	// Get object ID from mapping
   154→	if objectMap == nil {
   155→		fmt.Printf("[%s] ✗ Object map not initialized\n", time.Now().Format(time.RFC3339))
   156→		return
   157→	}
   158→
   159→	objectID, exists := objectMap.Get(filenameNoExt)
   160→	if !exists {
   161→		fmt.Printf("[%s] ⚠ No object ID found for %s (may have been deleted already)\n", time.Now().Format(time.RFC3339), filename)
   162→		return
   163→	}
   164→
   165→	if err := client.DeleteMarkdown(ctx, objectID); err != nil {
   166→		fmt.Printf("[%s] ✗ Delete error for %s: %v\n", time.Now().Format(time.RFC3339), filename, err)
   167→		return
   168→	}
   169→
   170→	// Remove from object map
   171→	if err := objectMap.Delete(filenameNoExt); err != nil {
   172→		fmt.Printf("[%s] ⚠ Failed to update object mapping: %v\n", time.Now().Format(time.RFC3339), err)
   173→	}
   174→
   175→	fmt.Printf("[%s] ✓ %s deleted from AnyType\n", time.Now().Format(time.RFC3339), filename)
   176→}
