   178→// WatchDirectory monitors for markdown file changes
   179→func WatchDirectory(ctx context.Context, dir string, client *AnyTypeClient, watcher *fsnotify.Watcher) error {
   180→	// Add root directory
   181→	if err := watcher.Add(dir); err != nil {
   182→		return err
   183→	}
   184→
   185→	// Add subdirectories
   186→	filepath.Walk(dir, func(path string, info os.FileInfo, err error) error {
   187→		if err != nil {
   188→			return err
   189→		}
   190→		if info.IsDir() && path != dir {
   191→			watcher.Add(path)
   192→		}
   193→		return nil
   194→	})
   195→
   196→	fmt.Printf("[%s] Watching %s for changes...\n", time.Now().Format(time.RFC3339), dir)
   197→
   198→	for {
   199→		select {
   200→		case event, ok := <-watcher.Events:
   201→			if !ok {
   202→				return nil
   203→			}
   204→
   205→			// Only process supported file types
   206→			if !isSupportedFile(event.Name) {
   207→				continue
   208→			}
   209→
   210→			// Check if event is recent (debounce)
   211→			now := time.Now()
   212→			if lastChange, exists := fileTimestamps[event.Name]; exists {
   213→				if now.Sub(lastChange) < debounceTime {
   214→					continue
   215→				}
   216→			}
   217→			fileTimestamps[event.Name] = now
   218→
   219→			// Handle different event types
   220→			if event.Op&fsnotify.Remove == fsnotify.Remove {
   221→				// File was deleted
   222→				DeleteFile(ctx, client, event.Name)
   223→			} else {
   224→				// Wait for file to stabilize
   225→				time.Sleep(debounceTime)
   226→
   227→				// Check if file still exists (for create/write events)
   228→				if _, err := os.Stat(event.Name); err == nil {
   229→					SyncFile(ctx, client, event.Name)
   230→				}
   231→			}
   232→
   233→		case err, ok := <-watcher.Errors:
   234→			if !ok {
   235→				return nil
   236→			}
   237→			fmt.Printf("[%s] Watcher error: %v\n", time.Now().Format(time.RFC3339), err)
   238→		}
   239→	}
   240→}
