   242→// InitialSync syncs all existing supported files
   243→func InitialSync(ctx context.Context, dir string, client *AnyTypeClient) error {
   244→	fmt.Printf("[%s] Running initial sync...\n", time.Now().Format(time.RFC3339))
   245→
   246→	files, err := os.ReadDir(dir)
   247→	if err != nil {
   248→		return err
   249→	}
   250→
   251→	for _, file := range files {
   252→		if !file.IsDir() && isSupportedFile(file.Name()) {
   253→			SyncFile(ctx, client, filepath.Join(dir, file.Name()))
   254→		}
   255→	}
   256→
   257→	fmt.Printf("[%s] Initial sync complete\n", time.Now().Format(time.RFC3339))
   258→	return nil
   259→}
