   261→func main() {
   262→	ctx := context.Background()
   263→
   264→	// Initialize object map
   265→	var err error
   266→	objectMap, err = NewObjectMap()
   267→	if err != nil {
   268→		fmt.Fprintf(os.Stderr, "Failed to initialize object map: %v\n", err)
   269→		os.Exit(1)
   270→	}
   271→
   272→	// Check workspace directory exists
   273→	if _, err := os.Stat(workspaceDir); os.IsNotExist(err) {
   274→		fmt.Fprintf(os.Stderr, "Error: %s does not exist\n", workspaceDir)
   275→		os.Exit(1)
   276→	}
   277→
   278→	// Create file watcher
   279→	watcher, err := fsnotify.NewWatcher()
   280→	if err != nil {
   281→		fmt.Fprintf(os.Stderr, "Failed to create watcher: %v\n", err)
   282→		os.Exit(1)
   283→	}
   284→	defer watcher.Close()
   285→
   286→	// Connect to AnyType gRPC (optional - continue if connection fails)
   287→	fmt.Printf("[%s] Connecting to AnyType at %s...\n", time.Now().Format(time.RFC3339), grpcAddr)
   288→	client, err := NewAnyTypeClient(grpcAddr)
   289→	if err != nil {
   290→		fmt.Printf("[%s] WARNING: Failed to connect to AnyType: %v\n", time.Now().Format(time.RFC3339), err)
   291→		fmt.Printf("[%s] Watcher will run but sync will be disabled until connection succeeds\n", time.Now().Format(time.RFC3339))
   292→		client = nil
   293→	} else {
   294→		defer client.Close()
   295→		fmt.Printf("[%s] Connected to AnyType\n", time.Now().Format(time.RFC3339))
   296→
   297→		// Health check
   298→		if err := client.HealthCheck(ctx); err != nil {
   299→			fmt.Printf("[%s] WARNING: Health check failed: %v\n", time.Now().Format(time.RFC3339), err)
   300→		}
   301→
   302→		// Open the space so we can create objects in it
   303→		fmt.Printf("[%s] Opening space %s...\n", time.Now().Format(time.RFC3339), spaceID)
   304→		if err := client.OpenSpace(ctx, spaceID); err != nil {
   305→			fmt.Printf("[%s] WARNING: Failed to open space: %v\n", time.Now().Format(time.RFC3339), err)
   306→			fmt.Printf("[%s] Will continue but sync may fail\n", time.Now().Format(time.RFC3339))
   307→		}
   308→	}
   309→
   310→	// Initial sync
   311→	if err := InitialSync(ctx, workspaceDir, client); err != nil {
   312→		fmt.Fprintf(os.Stderr, "Initial sync failed: %v\n", err)
   313→		os.Exit(1)
   314→	}
   315→
   316→	// Start watching
   317→	if err := WatchDirectory(ctx, workspaceDir, client, watcher); err != nil {
   318→		fmt.Fprintf(os.Stderr, "Watch failed: %v\n", err)
   319→		os.Exit(1)
   320→	}
   321→}
